1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"strings"
8		"testing"
9	)
10	
11	// repeatReader 无限重复输出单个字节 n 次，用于在不分配整块 64 MiB 的情况下
12	// 构造超长输入，同时让读路径经过大量 64 KiB 缓冲填充。
13	type repeatReader struct {
14		b byte
15		n int
16	}
17	
18	func (r *repeatReader) Read(p []byte) (int, error) {
19		if r.n == 0 {
20			return 0, io.EOF
21		}
22		c := len(p)
23		if c > r.n {
24			c = r.n
25		}
26		for i := range p[:c] {
27			p[i] = r.b
28		}
29		r.n -= c
30		return c, nil
31	}
32	
33	// failAfterReader 先透传前 n 个字节，随后返回固定错误，模拟真实读取故障。
34	type failAfterReader struct {
35		data []byte
36		n    int
37		err  error
38	}
39	
40	func (r *failAfterReader) Read(p []byte) (int, error) {
41		if r.n >= len(r.data) {
42			return 0, r.err
43		}
44		c := copy(p, r.data[r.n:])
45		r.n += c
46		if r.n >= len(r.data) {
47			return c, r.err
48		}
49		return c, nil
50	}
51	
52	// overlongLine 返回一段“合法 JSON 前缀 + 空白填充”的超长行内容，
53	// 总长为 maxIngestLineBytes+delta，且不含换行。前缀里的采样点绝不能被写入。
54	func overlongLine(delta int) io.Reader {
55		prefix := `[{"name":"cpu","timestamp":2000,"value":9},`
56		return io.MultiReader(
57			strings.NewReader(prefix),
58			&repeatReader{b: ' ', n: maxIngestLineBytes + delta - len(prefix)},
59		)
60	}
61	
62	func decodeResultLine(t *testing.T, line string) map[string]interface{} {
63		t.Helper()
64		var m map[string]interface{}
65		if err := json.Unmarshal([]byte(line), &m); err != nil {
66			t.Fatalf("invalid JSON result %q: %v", line, err)
67		}
68		return m
69	}
70	
71	func TestRunIngestLineExactlyAtSizeLimitStillProcessed(t *testing.T) {
72		// 内容恰好 67,108,864 字节（外层一对方括号之间全部是空白），仍应进入处理。
73		input := io.MultiReader(
74			strings.NewReader("["),
75			&repeatReader{b: ' ', n: maxIngestLineBytes - 2},
76			strings.NewReader("]\n"),
77		)
78		var out bytes.Buffer
79		if code := runIngest(input, &out); code != 0 {
80			t.Fatalf("exit code = %d, want 0 for a line exactly at the limit", code)
81		}
82		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
83		if len(lines) != 1 {
84			t.Fatalf("got %d output lines, want 1", len(lines))
85		}
86		m := decodeResultLine(t, lines[0])
87		if m["status"] != "ok" || m["added"].(float64) != 0 {
88			t.Fatalf("exact-limit line result = %v, want ok empty batch", m)
89		}
90	}
