181	func TestRunIngestOverlongFinalLineWithoutNewlineReportedOnce(t *testing.T) {
182		input := io.MultiReader(
183			strings.NewReader("[]\n"), // 行 1：正常
184			overlongLine(1),           // 行 2：超长且输入在此直接结束，没有最后一个换行
