467	// TestRunIngestLineLargerThanReadBufferStaysOneRequest 覆盖一条超过 64 KiB
468	// （读缓冲大小）、但远低于 64 MiB 上限的合法行：它跨越多个读取缓冲边界后
469	// 仍必须作为“一个”请求处理，只产出一条结果，而不是被缓冲边界拆成多条。
470	func TestRunIngestLineLargerThanReadBufferStaysOneRequest(t *testing.T) {
471		// 单个采样点的标签值是一段长文本（含多字节字符），使行内容约 80 KiB，
472		// 远大于 64 KiB 读缓冲、远小于 64 MiB 上限。
473		longVal := strings.Repeat("x😀", 20*1024) // 20480 个重复单元，约 80 KiB
474		bigLine := `[{"name":"big","timestamp":1,"value":1,"labels":{"pad":"` + longVal + `"}}]`
475		if len(bigLine) <= 64*1024 {
476			t.Fatalf("test setup: line only %d bytes, want > 64 KiB", len(bigLine))
477		}
478		if len(bigLine) >= maxIngestLineBytes {
479			t.Fatalf("test setup: line %d bytes must stay well under 64 MiB", len(bigLine))
480		}
481		data := []byte(bigLine + "\n" + `{"op":"query","name":"big","start":0,"end":10}` + "\n")
482	
483		baseCode, baseRes := baselineResults(t, data)
484		if baseCode != 0 {
485			t.Fatalf("baseline exit code = %d, want 0", baseCode)
486		}
487		if len(baseRes) != 2 || baseRes[0]["added"].(float64) != 1 {
488			t.Fatalf("baseline = %s, want one big write + one query", mustJSON(baseRes))
489		}
490		for _, v := range segmentationVariants(data) {
491			v := v
492			t.Run(v.label, func(t *testing.T) {
493				code, res := runIngestForSegmentation(t, v.in)
494				if code != 0 {
495					t.Fatalf("exit code = %d, want 0", code)
496				}
497				if len(res) != 2 {
498					t.Fatalf("%d results, want exactly 2 (one big write + one query, "+
499						"buffer boundaries must not split the line): %s", len(res), mustJSON(res))
500				}
501				if res[0]["status"] != "ok" || res[0]["added"].(float64) != 1 {
502					t.Fatalf("big write = %s, want one added point", mustJSON(res[0]))
503				}
504				arr := res[0]["series"].([]interface{})
505				if len(arr) != 1 {
506					t.Fatalf("series = %s, want 1", mustJSON(arr))
507				}
508				gotVal := arr[0].(map[string]interface{})["labels"].(map[string]interface{})["pad"].(string)
509				if gotVal != longVal {
510					t.Fatalf("long label value length = %d, want %d (no loss across buffers)",
511						len(gotVal), len(longVal))
512				}
513				q := res[1]["series"].([]interface{})
514				if len(q) != 1 || q[0].(map[string]interface{})["count"].(float64) != 1 {
515					t.Fatalf("query = %s, want the one big-line point", mustJSON(res[1]))
516				}
517			})
518		}
519	}
520	
521	// oneByte 只输出单个字节，然后 EOF；用于把分隔符本身单独作为一个片段送达。
522	type oneByte struct {
523		b byte
524		n int
525	}
526	
527	func (r *oneByte) Read(p []byte) (int, error) {
528		if r.n > 0 || len(p) == 0 {
529			if r.n > 0 {
530				return 0, io.EOF
531			}
532			return 0, nil
533		}
534		r.n++
535		p[0] = r.b
536		return 1, nil
537	}
538	
539	// TestRunIngestNewlineAndCRLFSeparatorsAcrossFragments 覆盖换行分隔符本身被
540	// 分段的情形：'\n' 作为单独片段送达，以及回车与换行分开送达。无论怎样分段，
541	// 结果条数、退出码与行号约定都必须与整份一次到达一致（沿用现有以 '\n'
542	// 分隔、'\r' 留在行尾、JSON 尾随空白被跳过的行为）。
543	func TestRunIngestNewlineAndCRLFSeparatorsAcrossFragments(t *testing.T) {
544		good := `[{"name":"m","timestamp":1,"value":1}]`
545	
546		// 场景 A：'\n' 单独送达，包括空白行的换行也单独送达；
547		// 行 3 "bad" 解析失败，错误行号必须仍指向真实行号 3。
548		aWhole := []byte(good + "\n\n" + "bad" + "\n" + "[]" + "\n")
549		aSplit := io.MultiReader(
550			bytes.NewReader([]byte(good)), &oneByte{b: '\n'},
551			&oneByte{b: '\n'}, // 空白行（行 2）的换行单独送达
552			bytes.NewReader([]byte("bad")), &oneByte{b: '\n'},
553			bytes.NewReader([]byte("[]")), &oneByte{b: '\n'},
554		)
555		t.Run("newline-as-its-own-fragment", func(t *testing.T) {
556			baseCode, baseRes := baselineResults(t, aWhole)
557			assertMatchesBaseline(t, "standalone newlines", aSplit, baseCode, baseRes)
558			if len(baseRes) != 3 {
559				t.Fatalf("%d results, want 3 (write ok, line-3 error, empty batch ok)", len(baseRes))
560			}
561			if baseRes[1]["status"] != "error" || int(baseRes[1]["line"].(float64)) != 3 {
562				t.Fatalf("error = %s, want parse failure on line 3", mustJSON(baseRes[1]))
563			}
564		})
565	
566		// 场景 B：'\r' 与 '\n' 分开送达（CRLF 的两部分各占一个片段）。
567		// 现状约定：以 '\n' 分隔，'\r' 留在行内容末尾；'\r' 是 JSON 空白，
568		// "[]\r" 仍是合法空批，"\r" 单独一行是空白行（无结果但占行号）。
569		bWhole := []byte("[]\r\n\r\n[]\n")
570		bSplit := io.MultiReader(
571			bytes.NewReader([]byte("[]\r")), &oneByte{b: '\n'},
572			bytes.NewReader([]byte("\r")), &oneByte{b: '\n'},
573			bytes.NewReader([]byte("[]")), &oneByte{b: '\n'},
574		)
575		t.Run("cr-and-lf-separate-fragments", func(t *testing.T) {
576			baseCode, baseRes := baselineResults(t, bWhole)
577			assertMatchesBaseline(t, "CRLF split", bSplit, baseCode, baseRes)
578			if baseCode != 0 || len(baseRes) != 2 {
579				t.Fatalf("baseline CRLF = code %d, %s; want code 0 and 2 results "+
580					"([]\\r ok, \\r blank, [] ok)", baseCode, mustJSON(baseRes))
581			}
582		})
583	}
584	
585	// TestRunIngestFinalLineWithoutNewlineProcessedOnce 输入正常结束时，最后一条
586	// 完整请求即使没有结尾换行，也应处理一次；分段送达下同样只处理一次、不重复。
587	func TestRunIngestFinalLineWithoutNewlineProcessedOnce(t *testing.T) {
588		data := []byte(`[{"name":"m","timestamp":1,"value":1}]` + "\n" + `[]`) // 末行无换行
589		baseCode, baseRes := baselineResults(t, data)
590		for _, v := range segmentationVariants(data) {
591			v := v
592			t.Run(v.label, func(t *testing.T) {
593				assertMatchesBaseline(t, v.label, v.in, baseCode, baseRes)
594			})
595		}
596		if baseCode != 0 || len(baseRes) != 2 {
597			t.Fatalf("baseline = code %d %s, want code 0 and exactly 2 results",
598				baseCode, mustJSON(baseRes))
599		}
600		if baseRes[0]["added"].(float64) != 1 || baseRes[1]["status"] != "ok" {
601			t.Fatalf("results = %s", mustJSON(baseRes))
602		}
603	}
604	
605	// TestRunIngestUnclosedFinalLineFailsWithoutCommit 若末行 JSON 尚未闭合（输入
606	// 结束），只报告该行解析失败，不带 index 或 conflict，也不返回成功写入结果；
607	// 分段不能使未闭合的前缀被当成一条完整请求。
608	func TestRunIngestUnclosedFinalLineFailsWithoutCommit(t *testing.T) {
609		good := `[{"name":"m","timestamp":1,"value":1}]`
610		data := []byte(good + "\n" + `[{"name":"m","timestamp":2,"value":2}`) // 缺 ] 且无换行
611		baseCode, baseRes := baselineResults(t, data)
612		for _, v := range segmentationVariants(data) {
613			v := v
614			t.Run(v.label, func(t *testing.T) {
615				assertMatchesBaseline(t, v.label, v.in, baseCode, baseRes)
616			})
617		}
618		if baseCode == 0 {
619			t.Fatalf("baseline exit code = 0, want non-zero for unclosed final line")
620		}
621		if len(baseRes) != 2 {
622			t.Fatalf("baseline %d results, want 2 (ok then one parse failure): %s",
623				len(baseRes), mustJSON(baseRes))
624		}
625		errLine := baseRes[1]
626		if errLine["status"] != "error" || int(errLine["line"].(float64)) != 2 {
627			t.Fatalf("final error = %s, want error on input line 2", mustJSON(errLine))
628		}
629		if _, has := errLine["index"]; has {
630			t.Fatalf("unclosed line error must not carry index: %s", mustJSON(errLine))
631		}
632		if _, has := errLine["conflict"]; has {
633			t.Fatalf("unclosed line error must not carry conflict: %s", mustJSON(errLine))
634		}
635		if !strings.Contains(errLine["error"].(string), "unexpected EOF") {
636			t.Fatalf("error = %q, want substring %q", errLine["error"], "unexpected EOF")
637		}
638	}
639	
640	// TestRunIngestCorruptTextAcrossFragmentsStillRejected 完整行里确实存在非法
641	// UTF-8 字节或孤立代理项时，分段不能使损坏文本被接受：仍应整行失败（无
642	// index/conflict），保留之前成功写入的数据，后续合法行继续处理，最终非零
643	// 退出。即使损坏字节或转义恰好在片段边界处分开送达，结论也不变。
644	func TestRunIngestCorruptTextAcrossFragmentsStillRejected(t *testing.T) {
645		good := `[{"name":"keep","timestamp":1,"value":1}]`
646		later := `[{"name":"later","timestamp":1,"value":1}]`
647		query := `{"op":"query","name":"keep","start":0,"end":10}`
648	
649		// 损坏行 A：name 中夹非法字节 0xFF；以及多字节序列被截断（E4 B8 后缺尾字节）。
650		badUTF8 := []byte(`[{"name":"cpu` + "\xff" + `","timestamp":1,"value":1}]`)
651		badUTF8Trunc := []byte(`[{"name":"abc` + "\xe4\xb8" + `","timestamp":1,"value":1}]`)
652		// 损坏行 B：孤立高代理项转义；孤立代理项的查询。
653		badSurrogate := []byte(`[{"name":"m\uD800","timestamp":1,"value":1}]`)
654		badSurrogateQuery := []byte(`{"op":"query","name":"m\uD800","start":0,"end":10}`)
655	
656		build := func(badLine []byte) []byte {
657			var b bytes.Buffer
658			b.WriteString(good)
659			b.WriteByte('\n')
660			b.Write(badLine)
661			b.WriteByte('\n')
662			b.WriteString(later)
663			b.WriteByte('\n')
664			b.WriteString(query)
665			b.WriteByte('\n')
666			return b.Bytes()
667		}
668	
669		cases := []struct {
670			name    string
671			badLine []byte
672			substr  string
673		}{
674			{"invalid-utf8-0xff", badUTF8, "UTF-8"},
675			{"invalid-utf8-truncated-multibyte", badUTF8Trunc, "UTF-8"},
676			{"lone-surrogate-write", badSurrogate, "surrogate"},
677			{"lone-surrogate-query", badSurrogateQuery, "surrogate"},
678		}
679	
680		for _, tc := range cases {
681			tc := tc
682			t.Run(tc.name, func(t *testing.T) {
683				data := build(tc.badLine)
684				baseCode, baseRes := baselineResults(t, data)
685	
686				// 在坏行的每个字节偏移处都放一条边界（包括坏行行首与转义各处）。
687				prefix := len(good) + 1
688				var cuts []int
689				for off := 0; off <= len(tc.badLine); off++ {
690					if d := prefix + off; d > 0 && d < len(data) {
691						cuts = append(cuts, d)
692					}
693				}
694				readers := []struct {
695					label string
696					in    io.Reader
697				}{
698					{"whole", bytes.NewReader(data)},
699					{"cut-at-every-bad-line-byte", newSegmentedReader(data, cuts...)},
700					{"1-byte", segments1Byte(data)},
701				}
702				// 对含 \u 转义的损坏行，再精确覆盖反斜杠之后到代理项结束的每个切开点。
703				for i := 0; i < len(data); i++ {
704					if data[i] == '\\' {
705						for k := 1; k <= 6 && i+k < len(data); k++ {
706							readers = append(readers, struct {
707								label string
708								in    io.Reader
709							}{
710								"split-in-escape@" + strconv.Itoa(i+k),
711								newSegmentedReader(data, i+k),
712							})
713						}
714					}
715				}
716	
717				for _, rd := range readers {
718					rd := rd
719					t.Run(rd.label, func(t *testing.T) {
720						assertMatchesBaseline(t, rd.label, rd.in, baseCode, baseRes)
721					})
722				}
723	
724				// 基准语义本身的断言（这些不随分段改变）。
725				if baseCode == 0 {
726					t.Fatalf("baseline exit code = 0, want non-zero")
727				}
728				if len(baseRes) != 4 {
729					t.Fatalf("baseline %d results, want 4 (good ok, bad error, later ok, query): %s",
730						len(baseRes), mustJSON(baseRes))
731				}
732				bad := baseRes[1]
733				if bad["status"] != "error" || int(bad["line"].(float64)) != 2 {
734					t.Fatalf("corrupt line = %s, want whole-line error on input line 2", mustJSON(bad))
735				}
736				if _, has := bad["index"]; has {
737					t.Fatalf("corrupt error must not carry index: %s", mustJSON(bad))
738				}
739				if _, has := bad["conflict"]; has {
740					t.Fatalf("corrupt error must not carry conflict: %s", mustJSON(bad))
741				}
742				if !strings.Contains(bad["error"].(string), tc.substr) {
743					t.Fatalf("error = %q, want substring %q", bad["error"], tc.substr)
744				}
745				// 坏行之后的合法写入继续处理；查询只见此前保留下来的 good 一个点。
746				if baseRes[2]["status"] != "ok" {
747					t.Fatalf("later legal line must still be processed: %s", mustJSON(baseRes[2]))
748				}
749				q := baseRes[3]["series"].([]interface{})
750				if len(q) != 1 {
751					t.Fatalf("query = %s, must retain only the earlier good point", mustJSON(baseRes[3]))
752				}
753			})
754		}
755	}
