13	// 本文件固定 ingest 的“结果输出故障”行为：当输出目标在接收当前结果时返回错误，
14	// runIngest 立即以退出码 1 结束，诊断只写入标准错误（ingest: write error: <原因>），
15	// 不向已失败的标准输出追加业务 JSON，不把它包装成带 line/index/conflict 的采样点错误，
16	// 不重试当前结果，也不再为剩余输入行（即使合法）产出任何结果。
17	// 这些测试通过向 io.Writer 注入故障在本机离线复现，不依赖真实磁盘写满或外部进程。
18	
19	// errResultSink 是离线注入的结果输出故障原因，必须原样出现在 stderr 诊断里。
20	var errResultSink = errors.New("simulated ingest result sink failure")
21	
22	// failingResultWriter 模拟结果输出目标在某条结果写出时返回错误。
23	// json.Encoder.Encode 对每条结果只发起一次 Write（JSON 与结尾 '\n' 在同一批字节中），
24	// runIngest 的输出路径上也没有其它缓冲，因此一次 Write 调用恰好对应一条待交付结果：
25	//   - 前 deliver 条结果完整接收（原样留存字节）；
26	//   - 下一条结果：partial==0 时整条拒绝（n=0, err），partial>0 时只接收其前 partial 字节，
27	//     用来模拟“当前结果只有一部分字节被接收就发生错误”；
28	//   - 按约定 runIngest 必须在首次故障后立即返回，因此 faultCalls 必须恒为 1。
29	type failingResultWriter struct {
30		buf        bytes.Buffer
31		deliver    int
32		partial    int
33		faultCalls int
34	}
35	
36	func (w *failingResultWriter) Write(p []byte) (int, error) {
37		if w.deliver > 0 {
38			w.deliver--
39			w.buf.Write(p)
40			return len(p), nil
41		}
42		w.faultCalls++
43		if w.partial > 0 {
44			n := w.partial
45			if n > len(p) {
46				n = len(p)
47			}
48			w.buf.Write(p[:n])
49			return n, errResultSink
50		}
51		return 0, errResultSink
52	}
53	
54	// captureStderr 临时把 os.Stderr 接到管道，同步执行 fn（runIngest 不启动 goroutine，
55	// 返回前所有 stderr 写入都已完成），返回退出码与捕获到的标准错误内容。
56	func captureStderr(t *testing.T, fn func() int) (int, string) {
57		t.Helper()
58		r, w, err := os.Pipe()
59		if err != nil {
60			t.Fatalf("pipe: %v", err)
61		}
62		old := os.Stderr
63		os.Stderr = w
64		code := fn()
65		os.Stderr = old
66		w.Close()
67		b, err := io.ReadAll(r)
68		if err != nil {
69			t.Fatalf("read captured stderr: %v", err)
70		}
71		return code, string(b)
72	}
73	
74	// splitRecordLines 把参考运行的输出切成逐条结果（每条都以 '\n' 结尾），保留原始字节。
75	func splitRecordLines(t *testing.T, b []byte) [][]byte {
76		t.Helper()
77		if len(b) == 0 {
78			t.Fatal("reference run produced no output")
79		}
80		var out [][]byte
81		for len(b) > 0 {
82			i := bytes.IndexByte(b, '\n')
83			if i < 0 {
84				t.Fatalf("reference output has an unterminated record: %q", b)
85			}
86			out = append(out, b[:i+1])
87			b = b[i+1:]
88		}
89		return out
90	}
91	
92	func joinedLines(lines ...string) io.Reader {
93		return strings.NewReader(strings.Join(lines, "\n") + "\n")
94	}
95	
96	// overlongThen 先放一条超长行（无结尾换行由调用方补），再接若干正常行。
97	func overlongThen(tail ...string) io.Reader {
98		return io.MultiReader(overlongLine(1),
99			strings.NewReader("\n"+strings.Join(tail, "\n")+"\n"))
100	}
101	
102	// overlongAfter 先放若干正常行，再放一条超长行，最后再接若干正常行。
103	func overlongAfter(head, tail []string) io.Reader {
104		return io.MultiReader(
105			strings.NewReader(strings.Join(head, "\n")+"\n"),
106			overlongLine(1),
107			strings.NewReader("\n"+strings.Join(tail, "\n")+"\n"),
108		)
109	}
110	
111	// assertTargetKind 校验参考输出中第 target 条结果确实是用例声明的类型，
112	// 保证“写不出去的那条”本身就是要覆盖的成功或失败结果，而不是测试构造失误。
113	func assertTargetKind(t *testing.T, kind string, raw []byte) {
114		t.Helper()
115		var m map[string]interface{}
116		if err := json.Unmarshal(raw, &m); err != nil {
117			t.Fatalf("target record %q is not valid JSON: %v", raw, err)
118		}
119		switch kind {
120		case "write-ok":
121			if m["status"] != "ok" || m["added"] == nil {
122				t.Fatalf("target = %v, want a write success carrying added", m)
123			}
124		case "query-ok":
125			if m["status"] != "ok" || m["op"] != "query" {
126				t.Fatalf("target = %v, want a query success", m)
127			}
128		case "parse-error":
129			assertErrorRecordShape(t, m, false, false)
130			if !strings.Contains(m["error"].(string), "invalid JSON") {
131				t.Fatalf("target error %v is not a whole-line parse error", m)
132			}
133		case "field-error":
134			assertErrorRecordShape(t, m, true, false)
135		case "query-error":
136			// 查询校验失败：普通输入失败，无 index、无 conflict，也不是整行解析失败。
137			assertErrorRecordShape(t, m, false, false)
138			if strings.Contains(m["error"].(string), "invalid JSON") {
139				t.Fatalf("target error %v must be a query validation error, not a parse error", m)
140			}
141		case "conflict-error":
142			assertErrorRecordShape(t, m, true, true)
143		case "overlong-error":
144			assertErrorRecordShape(t, m, false, false)
145			msg, _ := m["error"].(string)
146			if !strings.Contains(msg, "67108864") || !strings.Contains(msg, "single-line size limit") {
147				t.Fatalf("target error %q is not the size-limit error", msg)
148			}
149		default:
150			t.Fatalf("unknown case kind %q", kind)
151		}
152	}
153	
154	func assertErrorRecordShape(t *testing.T, m map[string]interface{}, wantIndex, wantConflict bool) {
155		t.Helper()
156		if m["status"] != "error" {
157			t.Fatalf("record = %v, want status error", m)
158		}
159		_, hasIndex := m["index"]
160		if hasIndex != wantIndex {
161			t.Fatalf("record %v index presence = %v, want %v", m, hasIndex, wantIndex)
162		}
163		_, hasConflict := m["conflict"]
164		if hasConflict != wantConflict {
165			t.Fatalf("record %v conflict presence = %v, want %v", m, hasConflict, wantConflict)
166		}
167	}
