172		newInput func() io.Reader // 参考运行与故障运行各调用一次，保证输入一致
173		target   int              // 目标结果是第几条（按输出顺序，从 1 开始）
174		records  int              // 参考运行应产出的结果总数
175		partial  bool             // false：目标结果整条被拒绝；true：只接收前半截字节
