181			w2 = `[{"name":"cpu","timestamp":2000,"value":2,"labels":{"host":"a"}}]`
182			w3 = `[{"name":"cpu","timestamp":3000,"value":3,"labels":{"host":"a"}}]`
183			q1 = `{"op":"query","name":"cpu","start":0,"end":4000,"labels":{"host":"a"}}`
184	
185			badParse = `not json`
186			badField = `[{"name":"cpu","timestamp":"soon","value":1}]`
187			// 查询校验失败：op 非法。无 index、无 conflict，是“普通输入失败”。
