189			// 与 w1 同序列同时间戳但值不同：数值冲突结果（带 index 与 conflict）。
190			badConflict = `[{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}]`
191		)
192	
193		return []writeFaultCase{
194			// 第一条结果到达时即被整条拒绝：成功结果（写入、查询）与各类失败结果适用同一条终止规则。
195			{"first write-ok rejected wholesale", "write-ok",
196				func() io.Reader { return joinedLines(w1, w2, q1) }, 1, 3, false},
197			{"first query-ok rejected wholesale", "query-ok",
198				// 首行为空白行：不产生结果但占行号，因此第一条“结果”就是查询成功。
199				func() io.Reader { return joinedLines("", q1, w2) }, 1, 2, false},
200			{"first parse-error rejected wholesale", "parse-error",
201				func() io.Reader { return joinedLines(badParse, w1, q1) }, 1, 3, false},
