203				func() io.Reader { return joinedLines(badField, w1, q1) }, 1, 3, false},
204			{"first query-error rejected wholesale", "query-error",
205				func() io.Reader { return joinedLines(badQuery, w1, q1) }, 1, 3, false},
206			{"first overlong-error rejected wholesale", "overlong-error",
207				func() io.Reader { return overlongThen(w1, q1) }, 1, 3, false},
