209			// 若干条结果已完整交付后目标才被整条拒绝：此前结果保留、顺序不变、不重发；
210			// 合法写入批次与有效查询同样立即终止；解析/字段/查询/冲突/超长行原本要返回的 error
211			// 结果写不出去时，也按输出故障结束，而不是沿用“失败行后继续处理后续行”的规则。
212			{"write-ok rejected after one delivered", "write-ok",
213				func() io.Reader { return joinedLines(w1, w2, q1) }, 2, 3, false},
214			{"query-ok rejected after two delivered", "query-ok",
215				func() io.Reader { return joinedLines(w1, w2, q1, w3) }, 3, 4, false},
216			{"parse-error rejected after two delivered", "parse-error",
217				func() io.Reader { return joinedLines(w1, w2, badParse, w3, q1) }, 3, 5, false},
218			{"field-error rejected after two delivered", "field-error",
219				func() io.Reader { return joinedLines(w1, w2, badField, w3, q1) }, 3, 5, false},
220			{"query-error rejected after two delivered", "query-error",
