227			// 目标结果只有一部分字节被接收就报错：不得补齐这条 JSON，片段不得被当成正常响应。
228			{"first write-ok partially received", "write-ok",
229				func() io.Reader { return joinedLines(w1, w2, q1) }, 1, 3, true},
230			{"first query-ok partially received", "query-ok",
