232			{"first query-error partially received", "query-error",
233				func() io.Reader { return joinedLines(badQuery, w1, q1) }, 1, 3, true},
234			{"write-ok partially received after two", "write-ok",
235				func() io.Reader { return joinedLines(w1, w2, w3, q1) }, 3, 4, true},
236			{"query-ok partially received after two", "query-ok",
237				func() io.Reader { return joinedLines(w1, w2, q1, w3) }, 3, 4, true},
238			{"parse-error partially received after two", "parse-error",
239				func() io.Reader { return joinedLines(w1, w2, badParse, w3, q1) }, 3, 5, true},
240			{"field-error partially received after two", "field-error",
241				func() io.Reader { return joinedLines(w1, w2, badField, w3, q1) }, 3, 5, true},
242			{"query-error partially received after two", "query-error",
243				func() io.Reader { return joinedLines(w1, w2, badQuery, w3, q1) }, 3, 5, true},
244			{"conflict-error partially received after two", "conflict-error",
245				func() io.Reader { return joinedLines(w1, w2, badConflict, w3, q1) }, 3, 5, true},
