349	// TestRunIngestWriteFailureDoesNotAppendBusinessError 单独锁定一个易回归点：
350	// 当一条 error 结果本身写不出去时，标准输出上除已接收的片段外不得再多出任何字节，
351	// 尤其不能出现第二条以 {"status":"error" 开头的记录。
352	func TestRunIngestWriteFailureDoesNotAppendBusinessError(t *testing.T) {
353		input := joinedLines(
354			`[{"name":"cpu","timestamp":1000,"value":1,"labels":{"host":"a"}}]`,
355			`not json`, // 目标：解析失败的 error 结果在输出时整条被拒
356			`[{"name":"cpu","timestamp":2000,"value":2,"labels":{"host":"a"}}]`,
357		)
358		var ref bytes.Buffer
359		runIngest(input, &ref)
360		records := splitRecordLines(t, ref.Bytes())
361		if len(records) != 3 {
362			t.Fatalf("reference records = %d, want 3", len(records))
363		}
364	
365		sink := &failingResultWriter{deliver: 1} // 第一条成功交付，第二条（error 结果）被拒
366		code, stderr := captureStderr(t, func() int {
367			return runIngest(joinedLines(
368				`[{"name":"cpu","timestamp":1000,"value":1,"labels":{"host":"a"}}]`,
369				`not json`,
370				`[{"name":"cpu","timestamp":2000,"value":2,"labels":{"host":"a"}}]`,
371			), sink)
372		})
373		if code != 1 {
374			t.Fatalf("exit code = %d, want 1", code)
375		}
376		if got, want := sink.buf.String(), string(records[0]); got != want {
377			t.Fatalf("stdout = %q, want only the first delivered record %q", got, want)
378		}
379		if sink.faultCalls != 1 {
380			t.Fatalf("sink faulted %d time(s), want 1", sink.faultCalls)
381		}
382		if !strings.HasPrefix(stderr, "ingest: write error: ") {
383			t.Fatalf("stderr = %q, want the write-error diagnostic on stderr", stderr)
